#include <grpcpp/grpcpp.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/kdf.h>
#include <string>
#include <vector>
#include <chrono>
#include <stdexcept>
#include <cstdlib>
#include <cstring>
#include "storage.grpc.pb.h"

using grpc::Server;
using grpc::ServerBuilder;
using grpc::ServerContext;
using grpc::Status;
using grpc::StatusCode;

enum class DecryptResult {
    SUCCESS,
    PADDING_ERROR,
    MAC_ERROR,
    FORMAT_ERROR
};

class CryptoEngine {
public:
    CryptoEngine() {
        // Load master key material from a secure source (env var, hex-encoded 32 bytes).
        // Do NOT hardcode secrets in the binary.
        const char* key_hex = std::getenv("STORAGE_MASTER_KEY_HEX");
        if (!key_hex) {
            throw std::runtime_error("STORAGE_MASTER_KEY_HEX not set");
        }
        std::string hex(key_hex);
        if (hex.size() != 64) {
            throw std::runtime_error("STORAGE_MASTER_KEY_HEX must be 64 hex chars (32 bytes)");
        }
        unsigned char master[32];
        for (size_t i = 0; i < 32; i++) {
            unsigned int byte = 0;
            if (sscanf(hex.c_str() + i * 2, "%2x", &byte) != 1) {
                throw std::runtime_error("Invalid hex in STORAGE_MASTER_KEY_HEX");
            }
            master[i] = static_cast<unsigned char>(byte);
        }

        // Derive independent encryption and MAC keys from the master key to avoid
        // reusing the same key for two cryptographic primitives.
        DeriveKey(master, 32, "encryption", enc_key_, 32);
        DeriveKey(master, 32, "mac", mac_key_, 32);
        OPENSSL_cleanse(master, sizeof(master));
    }

    ~CryptoEngine() {
        OPENSSL_cleanse(enc_key_, sizeof(enc_key_));
        OPENSSL_cleanse(mac_key_, sizeof(mac_key_));
    }

    // Encrypt with AES-256-CBC + HMAC-SHA256
    std::string Encrypt(const std::string& plaintext) {
        unsigned char iv[16];
        if (RAND_bytes(iv, 16) != 1) {
            throw std::runtime_error("RAND_bytes failed");
        }

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) throw std::runtime_error("EVP_CIPHER_CTX_new failed");

        if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, enc_key_, iv) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("EVP_EncryptInit_ex failed");
        }

        std::vector<unsigned char> ciphertext(plaintext.size() + 32);
        int len = 0, total = 0;
        if (EVP_EncryptUpdate(ctx, ciphertext.data(), &len,
                              (unsigned char*)plaintext.data(), plaintext.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("EVP_EncryptUpdate failed");
        }
        total = len;
        if (EVP_EncryptFinal_ex(ctx, ciphertext.data() + total, &len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            throw std::runtime_error("EVP_EncryptFinal_ex failed");
        }
        total += len;
        EVP_CIPHER_CTX_free(ctx);

        // Format: IV (16) || Ciphertext || HMAC (32)
        std::string result((char*)iv, 16);
        result.append((char*)ciphertext.data(), total);

        unsigned char hmac[32];
        ComputeHMAC(result, hmac);
        result.append((char*)hmac, 32);

        return result;
    }

    DecryptResult Decrypt(const std::string& blob, std::string& plaintext) {
        if (blob.size() < 48) return DecryptResult::FORMAT_ERROR;

        // Extract components
        std::string iv_and_ct = blob.substr(0, blob.size() - 32);
        std::string received_hmac = blob.substr(blob.size() - 32);

        // Verify HMAC first
        unsigned char computed_hmac[32];
        ComputeHMAC(iv_and_ct, computed_hmac);

        if (!ConstantTimeCompare((unsigned char*)received_hmac.data(),
                                  computed_hmac, 32)) {
            return DecryptResult::MAC_ERROR;
        }

        // Extract IV and ciphertext
        unsigned char iv[16];
        memcpy(iv, iv_and_ct.data(), 16);
        std::string ct = iv_and_ct.substr(16);

        // Decrypt
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        if (!ctx) return DecryptResult::FORMAT_ERROR;

        if (EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), nullptr, enc_key_, iv) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return DecryptResult::FORMAT_ERROR;
        }

        std::vector<unsigned char> pt(ct.size() + 16);
        int len = 0, total = 0;
        if (EVP_DecryptUpdate(ctx, pt.data(), &len,
                              (unsigned char*)ct.data(), ct.size()) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            return DecryptResult::PADDING_ERROR;
        }
        total = len;

        int ret = EVP_DecryptFinal_ex(ctx, pt.data() + total, &len);
        EVP_CIPHER_CTX_free(ctx);

        if (ret != 1) {
            return DecryptResult::PADDING_ERROR;
        }
        total += len;
        plaintext.assign((char*)pt.data(), total);
        return DecryptResult::SUCCESS;
    }

private:
    void ComputeHMAC(const std::string& data, unsigned char* out) {
        unsigned int hmac_len = 32;
        HMAC(EVP_sha256(), mac_key_, 32,
             (unsigned char*)data.data(), data.size(), out, &hmac_len);
    }

    // Simple HKDF-Expand style key derivation using HMAC-SHA256 with a label.
    void DeriveKey(const unsigned char* master, size_t master_len,
                   const std::string& label, unsigned char* out, size_t out_len) {
        // Single-block expand (out_len <= 32) with counter 0x01.
        std::string info = label;
        info.push_back((char)0x01);
        unsigned int len = 32;
        unsigned char tmp[32];
        HMAC(EVP_sha256(), master, (int)master_len,
             (unsigned char*)info.data(), info.size(), tmp, &len);
        memcpy(out, tmp, out_len);
        OPENSSL_cleanse(tmp, sizeof(tmp));
    }

    bool ConstantTimeCompare(const unsigned char* a, const unsigned char* b, size_t len) {
        unsigned char result = 0;
        for (size_t i = 0; i < len; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

    unsigned char enc_key_[32];
    unsigned char mac_key_[32];
};

class StorageServiceImpl final : public StorageService::Service {
public:
    Status Store(ServerContext* context, const StoreRequest* request,
                 StoreResponse* response) override {
        std::string encrypted = engine_.Encrypt(request->value());
        storage_[request->key()] = encrypted;
        response->set_success(true);
        return Status::OK;
    }

    Status Retrieve(ServerContext* context, const RetrieveRequest* request,
                    RetrieveResponse* response) override {
        auto it = storage_.find(request->key());
        if (it == storage_.end()) {
            return Status(StatusCode::NOT_FOUND, "Key not found");
        }
        std::string plaintext;
        DecryptResult result = engine_.Decrypt(it->second, plaintext);
        if (result == DecryptResult::SUCCESS) {
            response->set_value(plaintext);
            return Status::OK;
        }
        return Status(StatusCode::INTERNAL, "Decryption failed");
    }

    Status Update(ServerContext* context, const UpdateRequest* request,
                  UpdateResponse* response) override {
        auto it = storage_.find(request->key());
        if (it == storage_.end()) {
            return Status(StatusCode::NOT_FOUND, "Key not found");
        }

        // Client provides re-encrypted blob for migration
        std::string plaintext;
        DecryptResult result = engine_.Decrypt(request->new_blob(), plaintext);

        switch (result) {
            case DecryptResult::SUCCESS:
                storage_[request->key()] = request->new_blob();
                response->set_status("updated");
                return Status::OK;
            case DecryptResult::PADDING_ERROR:
                response->set_status("invalid_input");
                return Status(StatusCode::INVALID_ARGUMENT, "Decryption failed");
            case DecryptResult::MAC_ERROR:
                response->set_status("invalid_input");
                return Status(StatusCode::INVALID_ARGUMENT, "Decryption failed");
            case DecryptResult::FORMAT_ERROR:
                response->set_status("invalid_input");
                return Status(StatusCode::INVALID_ARGUMENT, "Decryption failed");
        }
        return Status(StatusCode::INTERNAL, "Unknown error");
    }

private:
    CryptoEngine engine_;
    std::unordered_map<std::string, std::string> storage_;
};

int main() {
    std::string server_address("0.0.0.0:50051");
    StorageServiceImpl service;
    ServerBuilder builder;
    builder.AddListeningPort(server_address, grpc::InsecureServerCredentials());
    builder.RegisterService(&service);
    std::unique_ptr<Server> server(builder.BuildAndStart());
    server->Wait();
    return 0;
}
